import type { Technology, TechnologyNarrative } from "@/lib/content-types";
import { localized } from "@/data/localized";

const essays: Record<string, TechnologyNarrative> = {
  html: {
    opening: [
      localized("Quase tudo o que você usa na web começa como uma descrição de conteúdo. Antes de existir botão animado, tema escuro ou chamada para uma API, alguém precisa dizer ao navegador o que é título, navegação, formulário, tabela ou artigo. Esse é o trabalho do HTML.", "Almost everything you use on the web begins as a description of content. Before animated buttons, dark themes or API calls, someone must tell the browser what is a heading, navigation, form, table or article. That is HTML's job.", "Casi todo lo que usas en la web empieza como una descripción del contenido. Antes de botones animados, tema oscuro o llamadas a una API, alguien debe decirle al navegador qué es título, navegación, formulario, tabla o artículo. Ese es el trabajo de HTML."),
      localized("Ele não é uma linguagem de programação e não precisa fingir ser. Seu valor está em criar uma estrutura que navegadores, mecanismos de busca, tecnologias assistivas e o restante do código consigam compreender.", "It is not a programming language and does not need to pretend to be one. Its value lies in creating a structure browsers, search engines, assistive technologies and the rest of the code can understand.", "No es un lenguaje de programación ni necesita parecerlo. Su valor está en crear una estructura que navegadores, buscadores, tecnologías de apoyo y el resto del código puedan comprender.")
    ],
    ecosystem: localized("HTML é a base sobre a qual CSS apresenta e JavaScript acrescenta comportamento. Frameworks podem gerar markup, mas não eliminam a responsabilidade de escolher elementos, hierarquia e nomes acessíveis corretamente.", "HTML is the foundation CSS presents and JavaScript adds behavior to. Frameworks may generate markup, but they do not remove the responsibility to choose elements, hierarchy and accessible names correctly.", "HTML es la base que CSS presenta y JavaScript hace interactiva. Los frameworks pueden generar markup, pero no eliminan la responsabilidad de elegir elementos, jerarquía y nombres accesibles correctamente."),
    decisions: localized("A principal decisão em HTML não é visual: é semântica. Um botão e um link podem parecer iguais, mas expressam ações diferentes. Quando a estrutura está errada, CSS e JavaScript costumam acumular correções frágeis para um problema que deveria ter sido resolvido no documento.", "The main HTML decision is not visual but semantic. A button and a link may look alike, yet express different actions. When structure is wrong, CSS and JavaScript often accumulate fragile fixes for a problem that belonged in the document.", "La principal decisión en HTML no es visual, sino semántica. Un botón y un enlace pueden verse iguales, pero expresan acciones distintas. Cuando la estructura está mal, CSS y JavaScript acumulan correcciones frágiles para un problema del documento."),
    gettingStarted: localized("Comece construindo uma página que continue compreensível sem CSS e utilizável sem mouse. Leia a estrutura pelo painel de acessibilidade do navegador, percorra tudo com Tab e só depois pense em componentes ou abstrações.", "Start by building a page that remains understandable without CSS and usable without a mouse. Read its structure through the browser accessibility tree, navigate everything with Tab and only then think about components or abstractions.", "Empieza creando una página comprensible sin CSS y utilizable sin ratón. Lee su estructura en el árbol de accesibilidad del navegador, recórrela con Tab y solo después piensa en componentes o abstracciones."),
    comparison: localized("HTML não concorre com React, Next.js ou qualquer framework. Essas ferramentas produzem e organizam interfaces; o resultado que chega ao navegador ainda precisa ser HTML coerente.", "HTML does not compete with React, Next.js or any framework. Those tools produce and organize interfaces; what reaches the browser still needs to be coherent HTML.", "HTML no compite con React, Next.js ni con ningún framework. Esas herramientas producen y organizan interfaces; lo que llega al navegador sigue necesitando HTML coherente.")
  },
  react: {
    opening: [
      localized("React nasceu para um problema que aparece quando interfaces deixam de ser páginas estáticas e passam a responder continuamente a dados e ações. Em vez de alterar o DOM passo a passo, você descreve como a interface deve parecer para um determinado estado.", "React emerged from a problem that appears when interfaces stop being static pages and continuously respond to data and actions. Instead of changing the DOM step by step, you describe what the interface should look like for a given state.", "React nació de un problema que aparece cuando las interfaces dejan de ser páginas estáticas y responden continuamente a datos y acciones. En vez de cambiar el DOM paso a paso, describes cómo debe verse la interfaz para un estado determinado."),
      localized("A ideia parece simples, mas muda a forma de organizar o front-end: componentes passam a representar responsabilidades visuais, dados fluem por uma árvore e atualizações precisam continuar previsíveis à medida que o produto cresce.", "The idea sounds simple, but changes how front-end code is organized: components represent visual responsibilities, data flows through a tree and updates must remain predictable as the product grows.", "La idea parece simple, pero cambia cómo se organiza el front-end: los componentes representan responsabilidades visuales, los datos fluyen por un árbol y las actualizaciones deben seguir siendo previsibles al crecer el producto.")
    ],
    ecosystem: localized("React é uma biblioteca de interface, não uma solução completa de aplicação. Roteamento, busca de dados, formulários, cache e renderização no servidor vêm de outras decisões — ou de frameworks como Next.js. Essa liberdade é útil, mas também explica por que dois projetos React podem ter arquiteturas muito diferentes.", "React is a UI library, not a complete application solution. Routing, data fetching, forms, caching and server rendering come from other decisions—or frameworks such as Next.js. That freedom is useful, but also explains why two React projects may have very different architectures.", "React es una biblioteca de interfaz, no una solución completa. Routing, acceso a datos, formularios, caché y renderizado en servidor vienen de otras decisiones o de frameworks como Next.js. Esa libertad es útil, pero explica por qué dos proyectos React pueden ser muy distintos."),
    decisions: localized("O desafio raramente é criar um componente; é decidir onde o estado deve viver, o que pode ser derivado e quais limites mantêm a interface compreensível. Efeitos usados para sincronizar tudo e componentes que conhecem o produto inteiro são sinais de que o modelo ficou confuso.", "The challenge is rarely creating a component; it is deciding where state should live, what can be derived and which boundaries keep the interface understandable. Effects used to synchronize everything and components that know the whole product signal a confused model.", "El reto rara vez es crear un componente; es decidir dónde vive el estado, qué puede derivarse y qué límites mantienen la interfaz comprensible. Efectos para sincronizar todo y componentes que conocen todo el producto indican un modelo confuso."),
    gettingStarted: localized("React faz mais sentido depois de HTML, CSS e JavaScript. Construa primeiro uma interface pequena com estado local, carregamento, erro e formulário; depois explique por que cada estado existe e como o usuário percebe a mudança.", "React makes more sense after HTML, CSS and JavaScript. First build a small interface with local state, loading, errors and a form; then explain why each state exists and how the user perceives the change.", "React tiene más sentido después de HTML, CSS y JavaScript. Construye primero una interfaz pequeña con estado local, carga, error y formulario; después explica por qué existe cada estado y cómo percibe el cambio la persona."),
    comparison: localized("Vue e Svelte resolvem a mesma família de problemas com modelos diferentes de template e reatividade. A escolha não deveria começar por qual é 'melhor', mas pelo ecossistema, pela experiência da equipe e pelo tipo de aplicação que será mantida.", "Vue and Svelte solve the same family of problems through different template and reactivity models. The choice should not begin with which is 'better', but with ecosystem, team experience and the kind of application that will be maintained.", "Vue y Svelte resuelven la misma familia de problemas con modelos distintos de templates y reactividad. La elección no debería empezar por cuál es 'mejor', sino por el ecosistema, la experiencia del equipo y el tipo de aplicación.")
  },
  python: {
    opening: [
      localized("Python costuma ser a primeira linguagem de muita gente porque permite transformar uma ideia em programa com pouco ruído sintático. Essa acessibilidade não significa que seja uma linguagem apenas para iniciantes: ela sustenta automações, análises, APIs, ciência e sistemas de machine learning.", "Python is often a first language because it turns an idea into a program with little syntactic noise. That accessibility does not make it a beginner-only language: it supports automation, analysis, APIs, science and machine-learning systems.", "Python suele ser el primer lenguaje de muchas personas porque convierte una idea en programa con poco ruido sintáctico. Esa accesibilidad no lo limita a principiantes: sostiene automatización, análisis, APIs, ciencia y sistemas de machine learning."),
      localized("O ponto forte é também uma fonte de confusão. Como é fácil começar, experimentos podem crescer sem ambiente isolado, testes, módulos ou limites claros. O salto do script útil para o software confiável exige método.", "Its strength is also a source of confusion. Because starting is easy, experiments may grow without isolated environments, tests, modules or clear boundaries. Moving from a useful script to reliable software requires method.", "Su fortaleza también genera confusión. Como es fácil empezar, los experimentos pueden crecer sin entorno aislado, pruebas, módulos ni límites claros. Pasar de script útil a software confiable exige método.")
    ],
    ecosystem: localized("Python muda bastante conforme a área. Em dados, convive com notebooks, SQL e bibliotecas numéricas; no back-end, com HTTP, frameworks e bancos; em automação, com o sistema operacional. Aprender a linguagem é só o núcleo comum — o restante depende do problema escolhido.", "Python changes considerably by field. In data it works with notebooks, SQL and numerical libraries; in back-end with HTTP, frameworks and databases; in automation with the operating system. Learning the language is only the common core—the rest depends on the chosen problem.", "Python cambia bastante según el área. En datos convive con notebooks, SQL y bibliotecas numéricas; en back-end con HTTP, frameworks y bases; en automatización con el sistema operativo. Aprender el lenguaje es solo el núcleo común."),
    decisions: localized("Python favorece legibilidade e velocidade de desenvolvimento, mas CPU intensiva, dependências nativas e distribuição podem exigir outra arquitetura. Nem todo problema precisa de micro-otimização; nem todo gargalo deve ser ignorado porque a sintaxe é agradável.", "Python favors readability and development speed, but CPU-intensive work, native dependencies and distribution may require another architecture. Not every problem needs micro-optimization; not every bottleneck should be ignored because the syntax is pleasant.", "Python favorece legibilidad y velocidad de desarrollo, pero CPU intensiva, dependencias nativas y distribución pueden exigir otra arquitectura. No todo problema necesita microoptimización ni todo cuello de botella debe ignorarse."),
    gettingStarted: localized("Escolha um problema pequeno que leia entrada, valide dados, trate erros e produza uma saída útil. Use ambiente virtual, testes e um README desde o começo; isso ensina mais sobre Python profissional que uma sequência longa de exercícios desconectados.", "Choose a small problem that reads input, validates data, handles errors and produces useful output. Use a virtual environment, tests and a README from the start; that teaches more about professional Python than a long sequence of disconnected exercises.", "Elige un problema pequeño que lea entrada, valide datos, trate errores y produzca una salida útil. Usa entorno virtual, pruebas y README desde el inicio; enseña más sobre Python profesional que muchos ejercicios desconectados."),
    comparison: localized("JavaScript é a escolha natural quando o navegador faz parte do problema; Java e C# trazem ecossistemas corporativos mais rígidos; Go oferece binários e concorrência com outro perfil. Python se destaca quando legibilidade e riqueza de bibliotecas importam mais que controle fino do runtime.", "JavaScript is natural when the browser is part of the problem; Java and C# provide stricter enterprise ecosystems; Go offers binaries and concurrency with a different profile. Python stands out when readability and library breadth matter more than fine runtime control.", "JavaScript es natural cuando el navegador forma parte del problema; Java y C# ofrecen ecosistemas empresariales más rígidos; Go ofrece binarios y concurrencia con otro perfil. Python destaca cuando importan legibilidad y bibliotecas.")
  },
  git: {
    opening: [
      localized("Git não existe apenas para guardar uma cópia do código. Ele registra uma sequência de decisões e permite que várias linhas de trabalho avancem sem depender de uma pasta compartilhada ou de arquivos chamados 'final-agora-vai'.", "Git does not exist merely to keep a copy of code. It records a sequence of decisions and lets multiple lines of work progress without a shared folder or files named 'final-really-final'.", "Git no existe solo para guardar una copia del código. Registra una secuencia de decisiones y permite que varias líneas de trabajo avancen sin carpetas compartidas ni archivos llamados 'final-ahora-sí'."),
      localized("Quando o histórico é bem cuidado, ele responde o que mudou, por que mudou e como voltar. Quando é tratado como botão de upload, continua funcionando, mas perde justamente a parte que ajuda equipes a investigar e colaborar.", "When history is cared for, it answers what changed, why and how to go back. When treated as an upload button, it still works, but loses the part that helps teams investigate and collaborate.", "Cuando el historial está bien cuidado, responde qué cambió, por qué y cómo volver. Cuando se trata como botón de upload, sigue funcionando, pero pierde lo que ayuda a investigar y colaborar.")
    ],
    ecosystem: localized("Git é a tecnologia de versionamento; GitHub e GitLab são plataformas ao redor dela. Commit, branch, merge e rebase existem localmente. Pull request, issue e pipeline são camadas de colaboração oferecidas pelos serviços.", "Git is the version-control technology; GitHub and GitLab are platforms around it. Commits, branches, merges and rebases exist locally. Pull requests, issues and pipelines are collaboration layers provided by services.", "Git es la tecnología de versionado; GitHub y GitLab son plataformas a su alrededor. Commit, branch, merge y rebase existen localmente. Pull request, issue y pipeline son capas de colaboración de los servicios."),
    decisions: localized("A qualidade do histórico depende do recorte. Um commit pequeno não é o que altera poucas linhas, mas o que representa uma mudança coerente e reversível. Rebase e merge não são rituais rivais: são formas diferentes de integrar histórias com efeitos que a equipe precisa compreender.", "History quality depends on boundaries. A small commit is not one with few lines, but one representing a coherent, reversible change. Rebase and merge are not rival rituals; they integrate histories differently, with effects the team must understand.", "La calidad del historial depende del recorte. Un commit pequeño no es el de pocas líneas, sino el que representa un cambio coherente y reversible. Rebase y merge no son rituales rivales: integran historias de forma distinta."),
    gettingStarted: localized("Pratique em um repositório descartável: altere arquivos, leia status e diff, crie branches, provoque um conflito e recupere um commit. Entender o estado antes do comando é mais valioso que decorar uma lista de comandos.", "Practice in a disposable repository: change files, read status and diff, create branches, cause a conflict and recover a commit. Understanding state before choosing a command is more valuable than memorizing command lists.", "Practica en un repositorio descartable: cambia archivos, lee status y diff, crea branches, provoca un conflicto y recupera un commit. Entender el estado antes del comando vale más que memorizar comandos."),
    comparison: localized("Git não concorre com GitHub. Também não é igual a sistemas centralizados: cada clone contém histórico e permite trabalho local. Essa distribuição muda recuperação, colaboração e a forma como branches funcionam.", "Git does not compete with GitHub. It also differs from centralized systems: every clone contains history and supports local work. That distribution changes recovery, collaboration and how branches work.", "Git no compite con GitHub. Tampoco es igual a sistemas centralizados: cada clon contiene historial y permite trabajo local. Esa distribución cambia recuperación, colaboración y branches.")
  },
  postgresql: {
    opening: [
      localized("PostgreSQL entra em cena quando uma aplicação precisa lembrar fatos e preservar relações entre eles. Usuários, pedidos, pagamentos e permissões não são apenas objetos guardados: possuem regras que precisam continuar verdadeiras mesmo com concorrência e falhas.", "PostgreSQL enters when an application must remember facts and preserve relationships between them. Users, orders, payments and permissions are not merely stored objects; they have rules that must remain true under concurrency and failure.", "PostgreSQL entra cuando una aplicación necesita recordar hechos y preservar relaciones. Usuarios, pedidos, pagos y permisos no son solo objetos guardados: tienen reglas que deben seguir siendo ciertas ante concurrencia y fallos."),
      localized("Sua reputação de banco 'robusto' vem menos de um recurso isolado e mais da combinação de SQL, transações, constraints, extensibilidade e décadas de comportamento bem compreendido.", "Its reputation as a robust database comes less from one feature and more from the combination of SQL, transactions, constraints, extensibility and decades of well-understood behavior.", "Su reputación de base robusta viene menos de un recurso aislado y más de combinar SQL, transacciones, constraints, extensibilidad y décadas de comportamiento conocido.")
    ],
    ecosystem: localized("PostgreSQL costuma ficar atrás de APIs, pipelines de dados e produtos analíticos. ORMs facilitam acesso, mas não substituem modelagem nem leitura de planos. Serviços gerenciados reduzem parte da operação, sem eliminar decisões sobre índices, conexões, backup e restauração.", "PostgreSQL often sits behind APIs, data pipelines and analytical products. ORMs ease access but do not replace modeling or query-plan reading. Managed services reduce some operations without removing decisions about indexes, connections, backup and restoration.", "PostgreSQL suele estar detrás de APIs, pipelines de datos y productos analíticos. Los ORM facilitan acceso, pero no sustituyen modelado ni lectura de planes. Servicios gestionados reducen operación, no decisiones sobre índices, conexiones y backup."),
    decisions: localized("Escolher PostgreSQL implica aceitar um modelo relacional e investir em schema. Isso é vantagem quando integridade e consultas variadas importam; pode ser atrito quando o dado é efêmero, o acesso é estritamente chave-valor ou a distribuição exige outro compromisso.", "Choosing PostgreSQL means accepting a relational model and investing in schema. That helps when integrity and varied queries matter; it may be friction for ephemeral data, strictly key-value access or distribution requiring another compromise.", "Elegir PostgreSQL implica aceptar un modelo relacional e invertir en schema. Es ventaja cuando importan integridad y consultas variadas; puede ser fricción para datos efímeros, acceso clave-valor o distribución con otro compromiso."),
    gettingStarted: localized("Modele um domínio pequeno com chaves, constraints e uma transação real. Escreva consultas antes de adicionar ORM, leia o plano de uma consulta lenta e prove que consegue restaurar o backup. Esse percurso mostra o banco como sistema, não como arquivo de dados.", "Model a small domain with keys, constraints and a real transaction. Write queries before adding an ORM, read the plan of a slow query and prove you can restore the backup. This reveals the database as a system, not a data file.", "Modela un dominio pequeño con claves, constraints y una transacción real. Escribe consultas antes del ORM, lee el plan de una consulta lenta y demuestra que puedes restaurar el backup. Así ves la base como sistema."),
    comparison: localized("MySQL ocupa espaço semelhante e pode ser a escolha natural do ecossistema. MongoDB organiza documentos e pede outra modelagem. Redis privilegia acesso em memória e não substitui automaticamente o banco principal. A comparação começa pelas garantias e consultas, não por rankings.", "MySQL occupies similar ground and may be the ecosystem's natural choice. MongoDB organizes documents and asks for another model. Redis favors in-memory access and does not automatically replace the primary database. Compare guarantees and queries, not rankings.", "MySQL ocupa un espacio similar y puede ser la elección natural del ecosistema. MongoDB organiza documentos y exige otro modelo. Redis privilegia memoria y no sustituye automáticamente la base principal. Compara garantías y consultas, no rankings.")
  },
  docker: {
    opening: [
      localized("Docker reduz uma dor familiar: a aplicação funciona em uma máquina, mas encontra bibliotecas, versões e configurações diferentes em outra. Uma imagem descreve o ambiente de execução; um contêiner executa essa imagem como processo isolado.", "Docker reduces a familiar pain: an application works on one machine but finds different libraries, versions and configuration on another. An image describes the runtime environment; a container runs that image as an isolated process.", "Docker reduce un dolor conocido: la aplicación funciona en una máquina, pero encuentra bibliotecas, versiones y configuración distintas en otra. Una imagen describe el entorno; un contenedor ejecuta esa imagen como proceso aislado."),
      localized("O ganho não é 'virtualizar tudo', e sim tornar empacotamento e execução mais previsíveis. Isso ajuda desenvolvimento, CI e produção, desde que dados persistentes, segredos e sinais operacionais sejam tratados fora da ilusão de que o contêiner é uma máquina completa.", "The gain is not 'virtualizing everything' but making packaging and execution more predictable. That helps development, CI and production, as long as persistent data, secrets and operational signals are handled beyond the illusion that a container is a whole machine.", "La ventaja no es 'virtualizar todo', sino hacer más previsible el empaquetado y la ejecución. Ayuda en desarrollo, CI y producción si datos persistentes, secretos y señales se tratan fuera de la ilusión de que el contenedor es una máquina completa.")
    ],
    ecosystem: localized("Docker conversa com registros de imagens, Compose, pipelines e orquestradores. Kubernetes pode executar imagens compatíveis, mas adiciona uma plataforma operacional inteira. Aprender Docker não exige aprender Kubernetes em seguida.", "Docker works with image registries, Compose, pipelines and orchestrators. Kubernetes can run compatible images, but adds an entire operational platform. Learning Docker does not require learning Kubernetes next.", "Docker se conecta con registros de imágenes, Compose, pipelines y orquestadores. Kubernetes puede ejecutar imágenes compatibles, pero añade una plataforma operativa completa. Aprender Docker no obliga a seguir con Kubernetes."),
    decisions: localized("Cada camada, arquivo copiado e pacote instalado afeta tamanho, cache e superfície de ataque. Rodar como root ou colocar segredo na imagem pode parecer conveniente localmente e se tornar um problema sério quando o artefato é distribuído.", "Every layer, copied file and installed package affects size, caching and attack surface. Running as root or placing secrets in an image may seem convenient locally and become serious once the artifact is distributed.", "Cada capa, archivo copiado y paquete instalado afecta tamaño, caché y superficie de ataque. Ejecutar como root o poner secretos en la imagen parece cómodo localmente y se vuelve grave al distribuir el artefacto."),
    gettingStarted: localized("Empacote uma aplicação que você já entende. Escreva o Dockerfile, inspecione as camadas, rode com usuário sem privilégio e conecte a um banco pelo Compose. Depois pare tudo e verifique o que deveria — e o que não deveria — ter persistido.", "Package an application you already understand. Write its Dockerfile, inspect layers, run as a non-root user and connect it to a database through Compose. Then stop everything and verify what should—and should not—have persisted.", "Empaqueta una aplicación que ya entiendes. Escribe el Dockerfile, inspecciona capas, ejecuta sin root y conecta una base con Compose. Después detén todo y verifica qué debía persistir y qué no."),
    comparison: localized("Uma máquina virtual inclui outro sistema operacional; um contêiner compartilha o kernel do host. Podman resolve parte do mesmo problema com outra arquitetura. A escolha prática depende do ambiente, integração e modelo de segurança, não apenas da sintaxe dos comandos.", "A virtual machine includes another operating system; a container shares the host kernel. Podman solves part of the same problem with another architecture. The practical choice depends on environment, integration and security model, not just command syntax.", "Una máquina virtual incluye otro sistema operativo; un contenedor comparte el kernel del host. Podman resuelve parte del mismo problema con otra arquitectura. La elección depende del entorno, integración y seguridad, no solo de comandos.")
  },
  linux: {
    opening: [
      localized("Linux aparece no DevAtlas não porque todo mundo precise abandonar seu computador atual, mas porque grande parte dos servidores, contêineres, dispositivos e plataformas cloud executa sobre ele. Entender Linux é aprender a observar um sistema enquanto ele trabalha.", "Linux appears in DevAtlas not because everyone must replace their current computer, but because much of servers, containers, devices and cloud platforms runs on it. Understanding Linux means learning to observe a system while it works.", "Linux aparece en DevAtlas no porque todos deban cambiar su computadora, sino porque gran parte de servidores, contenedores, dispositivos y plataformas cloud se ejecuta sobre él. Entender Linux es aprender a observar un sistema mientras trabaja."),
      localized("Arquivos, usuários, processos, permissões, rede e serviços deixam de ser botões de um painel e passam a formar um modelo que pode ser investigado, automatizado e documentado.", "Files, users, processes, permissions, networking and services stop being dashboard buttons and become a model that can be investigated, automated and documented.", "Archivos, usuarios, procesos, permisos, red y servicios dejan de ser botones de un panel y forman un modelo que puede investigarse, automatizarse y documentarse.")
    ],
    ecosystem: localized("Shell e terminal são interfaces, não sinônimos de Linux. Docker usa recursos do kernel; NGINX e bancos costumam rodar como serviços; cloud oferece máquinas Linux prontas. Quanto melhor a base, menos essas ferramentas parecem caixas-pretas.", "Shell and terminal are interfaces, not synonyms for Linux. Docker uses kernel features; NGINX and databases commonly run as services; cloud offers ready Linux machines. The stronger the foundation, the less these tools feel like black boxes.", "Shell y terminal son interfaces, no sinónimos de Linux. Docker usa recursos del kernel; NGINX y bases suelen ejecutarse como servicios; cloud ofrece máquinas Linux. Cuanto mejor la base, menos parecen cajas negras."),
    decisions: localized("A distribuição muda pacotes e convenções, mas os fundamentos são transferíveis. A decisão importante não é decorar comandos de uma distro: é saber descobrir estado, aplicar menor privilégio e alterar o sistema de forma verificável e reversível.", "Distributions change packages and conventions, but foundations transfer. The important decision is not memorizing one distro's commands: it is discovering state, applying least privilege and changing the system in a verifiable, reversible way.", "La distribución cambia paquetes y convenciones, pero las bases se transfieren. Lo importante no es memorizar comandos: es descubrir estado, aplicar mínimo privilegio y cambiar el sistema de forma verificable y reversible."),
    gettingStarted: localized("Use uma máquina virtual ou contêiner de laboratório. Crie usuários, ajuste permissões, execute um serviço, leia seus logs e provoque uma falha controlada. Registre o diagnóstico em vez de guardar apenas o comando que resolveu.", "Use a lab virtual machine or container. Create users, adjust permissions, run a service, read its logs and cause a controlled failure. Record the diagnosis instead of keeping only the command that fixed it.", "Usa una máquina virtual o contenedor de laboratorio. Crea usuarios, ajusta permisos, ejecuta un servicio, lee logs y provoca un fallo controlado. Registra el diagnóstico, no solo el comando que lo resolvió."),
    comparison: localized("Windows também é sistema operacional e domina muitos ambientes corporativos e desktops. A diferença relevante para estudo é o ecossistema e o modelo operacional do destino, não uma disputa abstrata sobre qual sistema é superior.", "Windows is also an operating system and dominates many enterprise and desktop environments. The relevant study difference is the target ecosystem and operating model, not an abstract contest over which system is superior.", "Windows también es sistema operativo y domina muchos entornos empresariales y desktop. La diferencia relevante es el ecosistema y modelo operativo del destino, no una disputa abstracta sobre superioridad.")
  },
  kubernetes: {
    opening: [
      localized("Kubernetes começa a fazer sentido quando executar um contêiner deixa de ser o problema principal. Em uma plataforma com muitos serviços, máquinas e equipes, alguém precisa decidir onde cada workload roda, como recebe tráfego, como se recupera e quais recursos pode consumir.", "Kubernetes starts making sense when running one container is no longer the main problem. In a platform with many services, machines and teams, something must decide where each workload runs, how it receives traffic, how it recovers and which resources it may consume.", "Kubernetes empieza a tener sentido cuando ejecutar un contenedor deja de ser el problema principal. En una plataforma con muchos servicios, máquinas y equipos, algo debe decidir dónde corre cada workload, cómo recibe tráfico, cómo se recupera y qué recursos consume."),
      localized("Ele automatiza parte dessa coordenação por meio de um estado desejado. Você declara o que espera; controladores observam o cluster e tentam aproximar a realidade dessa declaração.", "It automates part of that coordination through desired state. You declare what you expect; controllers observe the cluster and try to move reality toward that declaration.", "Automatiza parte de esa coordinación mediante un estado deseado. Declaras lo esperado; controladores observan el clúster e intentan acercar la realidad a esa declaración.")
    ],
    ecosystem: localized("Kubernetes depende de imagens, rede, DNS, armazenamento, identidade e observabilidade. Helm, Argo CD e service meshes aparecem ao redor, mas cada camada aumenta o que precisa ser operado. O ecossistema é uma caixa de ferramentas, não uma sequência obrigatória.", "Kubernetes depends on images, networking, DNS, storage, identity and observability. Helm, Argo CD and service meshes appear around it, but every layer increases operational responsibility. The ecosystem is a toolbox, not a mandatory sequence.", "Kubernetes depende de imágenes, red, DNS, almacenamiento, identidad y observabilidad. Helm, Argo CD y service meshes aparecen alrededor, pero cada capa aumenta la responsabilidad. El ecosistema es una caja de herramientas, no una secuencia obligatoria."),
    decisions: localized("A pergunta honesta é se a organização possui complexidade que Kubernetes consegue reduzir — e maturidade para operar a complexidade que ele introduz. Para um produto pequeno, um serviço gerenciado ou uma VM bem cuidada costuma ser mais clara e barata.", "The honest question is whether the organization has complexity Kubernetes can reduce—and maturity to operate the complexity it introduces. For a small product, a managed service or well-run VM is often clearer and cheaper.", "La pregunta honesta es si la organización tiene complejidad que Kubernetes pueda reducir y madurez para operar la que introduce. Para un producto pequeño, un servicio gestionado o una VM bien cuidada suele ser más clara y barata."),
    gettingStarted: localized("Chegue depois de Linux, redes e contêineres. Em um cluster local, execute dois serviços, configure probes e limites, quebre uma dependência e acompanhe a recuperação. O aprendizado está no comportamento observado, não em acumular manifests.", "Come after Linux, networking and containers. In a local cluster, run two services, configure probes and limits, break a dependency and observe recovery. Learning lies in observed behavior, not accumulated manifests.", "Llega después de Linux, redes y contenedores. En un clúster local, ejecuta dos servicios, configura probes y límites, rompe una dependencia y observa la recuperación. El aprendizaje está en el comportamiento, no en acumular manifests."),
    comparison: localized("Docker empacota e executa contêineres; Kubernetes coordena muitos deles. ECS, Nomad e plataformas serverless resolvem partes semelhantes com diferentes níveis de controle e operação. A escala relevante inclui equipes e mudanças, não apenas número de requisições.", "Docker packages and runs containers; Kubernetes coordinates many of them. ECS, Nomad and serverless platforms solve similar parts with different control and operational levels. Relevant scale includes teams and change, not only request counts.", "Docker empaqueta y ejecuta contenedores; Kubernetes coordina muchos. ECS, Nomad y plataformas serverless resuelven partes similares con distintos niveles de control y operación. La escala incluye equipos y cambios, no solo solicitudes.")
  },
  aws: {
    opening: [
      localized("AWS não é uma tecnologia única, mas um catálogo de recursos de computação entregues como serviço. O valor está em obter capacidade, rede, armazenamento e serviços gerenciados sem construir um data center — assumindo, em troca, decisões contínuas de arquitetura, segurança e custo.", "AWS is not one technology but a catalog of computing resources delivered as services. Its value is obtaining capacity, networking, storage and managed services without building a data center—in exchange for ongoing architecture, security and cost decisions.", "AWS no es una sola tecnología, sino un catálogo de recursos de computación como servicio. Su valor está en obtener capacidad, red, almacenamiento y servicios gestionados sin construir un data center, a cambio de decisiones continuas de arquitectura, seguridad y costo."),
      localized("A quantidade de serviços pode intimidar iniciantes. Você não precisa memorizar o catálogo: precisa reconhecer os blocos fundamentais e aprender a fazer perguntas sobre identidade, rede, dados, falhas e cobrança.", "The number of services can intimidate beginners. You do not need to memorize the catalog; you need to recognize fundamental building blocks and ask questions about identity, networking, data, failure and billing.", "La cantidad de servicios puede intimidar. No necesitas memorizar el catálogo: necesitas reconocer bloques fundamentales y hacer preguntas sobre identidad, red, datos, fallos y facturación.")
    ],
    ecosystem: localized("EC2 oferece máquinas, S3 armazena objetos, RDS gerencia bancos e Lambda executa funções, mas nomes não formam arquitetura. Terraform pode descrever recursos; CloudWatch observa parte do ambiente; IAM atravessa tudo. A combinação deve nascer do problema.", "EC2 provides machines, S3 stores objects, RDS manages databases and Lambda runs functions, but names do not make architecture. Terraform can describe resources; CloudWatch observes parts of the environment; IAM crosses everything. Combinations must start from the problem.", "EC2 ofrece máquinas, S3 guarda objetos, RDS gestiona bases y Lambda ejecuta funciones, pero los nombres no forman arquitectura. Terraform describe recursos; CloudWatch observa parte del entorno; IAM atraviesa todo. La combinación nace del problema."),
    decisions: localized("Serviço gerenciado troca controle por menos operação. Alta disponibilidade aumenta custo e desenho. Dados entre regiões ou para fora da AWS podem custar. A responsabilidade compartilhada significa que o provedor protege a infraestrutura, enquanto você ainda configura acesso e uso corretamente.", "Managed services trade control for less operation. High availability increases cost and design. Data moving across regions or out of AWS may cost money. Shared responsibility means the provider protects infrastructure while you still configure access and usage correctly.", "Un servicio gestionado cambia control por menos operación. Alta disponibilidad aumenta costo y diseño. Mover datos entre regiones o fuera puede costar. Responsabilidad compartida significa que el proveedor protege infraestructura y tú configuras acceso y uso."),
    gettingStarted: localized("Comece com um ambiente mínimo e um orçamento baixo. Crie acesso de menor privilégio, publique uma aplicação simples, ative logs e alerta de custo e depois remova os recursos. Saber encerrar o laboratório é parte da competência.", "Start with a minimal environment and a low budget. Create least-privilege access, deploy a simple application, enable logs and a cost alert, then remove the resources. Knowing how to shut down the lab is part of the skill.", "Empieza con un entorno mínimo y presupuesto bajo. Crea acceso de mínimo privilegio, publica una aplicación, activa logs y alerta de costo y elimina los recursos. Saber cerrar el laboratorio forma parte de la competencia."),
    comparison: localized("Azure e Google Cloud oferecem blocos equivalentes com ecossistemas e pontos fortes diferentes. A primeira nuvem costuma ser escolhida pelo contexto da empresa, não por uma superioridade universal. Fundamentos de rede, identidade e custo são mais transferíveis que nomes de produtos.", "Azure and Google Cloud provide equivalent building blocks with different ecosystems and strengths. A first cloud is usually chosen by company context, not universal superiority. Networking, identity and cost foundations transfer better than product names.", "Azure y Google Cloud ofrecen bloques equivalentes con ecosistemas y fortalezas distintos. La primera nube suele elegirse por contexto empresarial, no superioridad universal. Redes, identidad y costo se transfieren mejor que nombres de productos.")
  },
  owasp: {
    opening: [
      localized("OWASP é uma comunidade e o Top 10 é um documento de conscientização, não uma ferramenta que 'faz segurança'. Ele organiza classes recorrentes de risco para ajudar equipes a reconhecer problemas antes que virem incidentes.", "OWASP is a community, and the Top 10 is an awareness document—not a tool that 'does security'. It organizes recurring risk classes so teams can recognize problems before they become incidents.", "OWASP es una comunidad y el Top 10 es un documento de concienciación, no una herramienta que 'hace seguridad'. Organiza clases recurrentes de riesgo para reconocer problemas antes de que se vuelvan incidentes."),
      localized("Seu papel é criar uma linguagem comum entre desenvolvimento, testes e segurança. A lista muda porque o ecossistema muda; usá-la como checklist permanente ou ranking exato perde a intenção do material.", "Its role is to create shared language among development, testing and security. The list changes because the ecosystem changes; using it as a permanent checklist or exact ranking misses its purpose.", "Su papel es crear un lenguaje común entre desarrollo, pruebas y seguridad. La lista cambia porque cambia el ecosistema; usarla como checklist permanente o ranking exacto pierde su intención.")
    ],
    ecosystem: localized("O Top 10 se conecta a autenticação, autorização, criptografia, validação, dependências e logging. Ferramentas como SonarQube ou scanners podem encontrar sinais, mas nenhum scanner entende sozinho regras de negócio e impacto.", "The Top 10 connects to authentication, authorization, cryptography, validation, dependencies and logging. Tools such as SonarQube or scanners may find signals, but no scanner alone understands business rules and impact.", "El Top 10 se conecta con autenticación, autorización, criptografía, validación, dependencias y logging. Herramientas como SonarQube o scanners encuentran señales, pero ninguna entiende sola reglas de negocio e impacto."),
    decisions: localized("Segurança não significa aplicar todos os controles com a mesma força. O trabalho é entender ativos, ameaças e impacto para escolher controles proporcionais. Uma categoria do Top 10 inicia uma investigação; não substitui threat modeling nem teste contextual.", "Security does not mean applying every control with equal force. The work is understanding assets, threats and impact to choose proportionate controls. A Top 10 category starts an investigation; it does not replace threat modeling or contextual testing.", "Seguridad no significa aplicar todos los controles igual. El trabajo es entender activos, amenazas e impacto para elegir controles proporcionales. Una categoría inicia una investigación; no sustituye threat modeling ni pruebas contextuales."),
    gettingStarted: localized("Escolha uma aplicação deliberadamente vulnerável em laboratório autorizado. Para uma categoria, explique a causa, demonstre o impacto, corrija no código e escreva um teste que impeça regressão. O valor está no raciocínio completo, não na captura do alerta.", "Choose an intentionally vulnerable application in an authorized lab. For one category, explain the cause, demonstrate impact, fix the code and write a regression test. The value lies in the complete reasoning, not an alert screenshot.", "Elige una aplicación deliberadamente vulnerable en laboratorio autorizado. Para una categoría, explica la causa, demuestra impacto, corrige el código y escribe una prueba de regresión. El valor está en el razonamiento completo."),
    comparison: localized("O Top 10 é uma referência de conscientização. ASVS oferece requisitos de verificação mais detalhados; threat modeling analisa um sistema específico; scanners automatizam verificações limitadas. Eles se complementam, não se substituem.", "The Top 10 is an awareness reference. ASVS provides more detailed verification requirements; threat modeling analyzes a specific system; scanners automate limited checks. They complement rather than replace one another.", "El Top 10 es una referencia de concienciación. ASVS ofrece requisitos más detallados; threat modeling analiza un sistema específico; scanners automatizan verificaciones limitadas. Se complementan.")
  },
  figma: {
    opening: [
      localized("Figma melhora uma conversa que antes ficava espalhada entre arquivos, capturas e reuniões: como uma experiência deve funcionar, quais padrões se repetem e o que design e engenharia precisam alinhar antes de construir.", "Figma improves a conversation once scattered across files, screenshots and meetings: how an experience should work, which patterns repeat and what design and engineering must align before building.", "Figma mejora una conversación antes dispersa entre archivos, capturas y reuniones: cómo debe funcionar una experiencia, qué patrones se repiten y qué deben alinear diseño e ingeniería antes de construir."),
      localized("A ferramenta ajuda a materializar hipóteses em fluxos, componentes e protótipos. Ela não produz evidência sobre o problema sozinha; uma tela detalhada continua sendo apenas uma hipótese até ser confrontada com contexto e pessoas.", "The tool materializes hypotheses as flows, components and prototypes. It does not produce evidence about the problem by itself; a polished screen remains a hypothesis until confronted with context and people.", "La herramienta materializa hipótesis en flujos, componentes y prototipos. No produce evidencia por sí sola; una pantalla detallada sigue siendo hipótesis hasta confrontarla con contexto y personas.")
    ],
    ecosystem: localized("Figma se conecta a pesquisa, arquitetura de informação, conteúdo, design systems e handoff. Maze pode apoiar testes de protótipo; HTML e CSS mostram o que a implementação realmente permite. A ponte funciona melhor quando decisões e estados são documentados, não apenas medidas.", "Figma connects to research, information architecture, content, design systems and handoff. Maze can support prototype testing; HTML and CSS reveal what implementation actually allows. The bridge works better when decisions and states are documented, not just measurements.", "Figma se conecta con investigación, arquitectura de información, contenido, design systems y handoff. Maze puede apoyar pruebas; HTML y CSS muestran lo que permite la implementación. El puente funciona mejor cuando se documentan decisiones y estados."),
    decisions: localized("Alta fidelidade cedo demais pode esconder dúvidas importantes. Componentes e variáveis ajudam consistência, mas exigem governança; transformar cada detalhe em componente torna a biblioteca tão difícil de usar quanto uma interface inconsistente.", "High fidelity too early can hide important questions. Components and variables support consistency but require governance; turning every detail into a component makes the library as hard to use as an inconsistent interface.", "Alta fidelidad demasiado pronto puede ocultar dudas importantes. Componentes y variables ayudan a consistencia, pero exigen gobierno; convertir cada detalle en componente vuelve la biblioteca difícil de usar."),
    gettingStarted: localized("Escolha um fluxo real, desenhe primeiro a estrutura e os estados, depois crie um protótipo que outra pessoa consiga percorrer sem explicação. Registre o que mudou após o teste e só então organize os padrões reutilizáveis.", "Choose a real flow, first design its structure and states, then create a prototype another person can navigate without explanation. Record what changed after testing and only then organize reusable patterns.", "Elige un flujo real, diseña primero estructura y estados, después crea un prototipo que otra persona recorra sin explicación. Registra lo que cambió tras la prueba y solo entonces organiza patrones reutilizables."),
    comparison: localized("Figma e ferramentas como Penpot resolvem colaboração e design de interface; não substituem pesquisa nem implementação. A escolha da ferramenta pesa menos que a qualidade do processo, a acessibilidade e a comunicação com quem construirá o produto.", "Figma and tools such as Penpot support collaboration and interface design; they do not replace research or implementation. Tool choice matters less than process quality, accessibility and communication with those building the product.", "Figma y herramientas como Penpot apoyan colaboración y diseño de interfaz; no sustituyen investigación ni implementación. La herramienta importa menos que el proceso, accesibilidad y comunicación.")
  },
  powerbi: {
    opening: [
      localized("Power BI fica visível nos dashboards, mas o trabalho importante acontece antes do gráfico: definir a pergunta, entender a fonte, organizar o modelo e decidir o que uma métrica realmente representa.", "Power BI is visible in dashboards, but the important work happens before the chart: defining the question, understanding the source, organizing the model and deciding what a metric actually represents.", "Power BI se ve en dashboards, pero el trabajo importante ocurre antes del gráfico: definir la pregunta, entender la fuente, organizar el modelo y decidir qué representa una métrica."),
      localized("Ele reúne preparação, modelagem, cálculos e distribuição em um ecossistema muito usado por organizações Microsoft. Isso permite entregar análise com rapidez, mas também facilita esconder regras de negócio em arquivos difíceis de revisar.", "It combines preparation, modeling, calculations and distribution in an ecosystem widely used by Microsoft organizations. That enables quick delivery, but also makes it easy to hide business rules inside files that are hard to review.", "Reúne preparación, modelado, cálculos y distribución en un ecosistema usado por organizaciones Microsoft. Permite entregar rápido, pero también ocultar reglas de negocio en archivos difíciles de revisar.")
    ],
    ecosystem: localized("Power Query prepara dados; o modelo relaciona tabelas; DAX calcula medidas no contexto da visualização; o serviço publica, atualiza e controla acesso. SQL, warehouses e dbt frequentemente preparam uma base mais confiável antes de o Power BI entrar.", "Power Query prepares data; the model relates tables; DAX calculates measures in visual context; the service publishes, refreshes and controls access. SQL, warehouses and dbt often prepare a more reliable base before Power BI enters.", "Power Query prepara datos; el modelo relaciona tablas; DAX calcula medidas en contexto; el servicio publica, actualiza y controla acceso. SQL, warehouses y dbt suelen preparar una base más confiable antes de Power BI."),
    decisions: localized("Um painel precisa decidir o que merece atenção e o que pode ser explorado. Mais visuais não significam mais clareza. Medidas, segurança por linha, atualização e definição compartilhada de métricas importam mais que efeitos e cores.", "A dashboard must decide what deserves attention and what can be explored. More visuals do not mean more clarity. Measures, row-level security, refresh and shared metric definitions matter more than effects and colors.", "Un panel debe decidir qué merece atención y qué puede explorarse. Más visuales no significan más claridad. Medidas, seguridad por fila, actualización y definición compartida importan más que efectos y colores."),
    gettingStarted: localized("Use um conjunto pequeno e uma pergunta concreta. Modele fatos e dimensões, crie poucas medidas verificáveis e peça para outra pessoa responder à pergunta usando o painel. Se ela interpretar o número de outra forma, o problema é de definição, não de decoração.", "Use a small dataset and a concrete question. Model facts and dimensions, create a few verifiable measures and ask someone else to answer the question through the dashboard. If they interpret the number differently, the problem is definition, not decoration.", "Usa un conjunto pequeño y una pregunta concreta. Modela hechos y dimensiones, crea pocas medidas verificables y pide a otra persona responder con el panel. Si interpreta el número de otra forma, el problema es definición, no decoración."),
    comparison: localized("Tableau e Looker Studio também criam análises visuais, com ecossistemas e modelos de governança diferentes. A escolha costuma seguir fontes, licenças e contexto da organização. O conhecimento transferível está em modelagem, métricas e comunicação.", "Tableau and Looker Studio also create visual analysis, with different ecosystems and governance models. Choice often follows sources, licensing and organizational context. Transferable knowledge lies in modeling, metrics and communication.", "Tableau y Looker Studio también crean análisis visual, con ecosistemas y modelos de gobierno distintos. La elección suele seguir fuentes, licencias y contexto. Lo transferible está en modelado, métricas y comunicación.")
  }
};

export const applyTechnologyEssays = (technologies: Technology[]) =>
  technologies.map((technology) => {
    const opening = [technology.explanation ?? technology.description];
    if (
      technology.problem
      && technology.problem.pt !== opening[0].pt
    ) opening.push(technology.problem);
    const fallback = technology.inPractice && technology.notPriorityWhen && technology.studyWhen
      ? {
          opening,
          ecosystem: technology.inPractice,
          decisions: technology.notPriorityWhen,
          gettingStarted: technology.studyWhen
        }
      : undefined;
    return {
      ...technology,
      narrative: essays[technology.id] ?? technology.narrative ?? fallback
    };
  });
